component_manifest_ts:
// Proposed file: src/core/schema/library/component.ts. Pure TS: no React, DOM or Tauri imports.
// Typechecked with tsc 6.0.3 (--strict --exactOptionalPropertyTypes --noUncheckedIndexedAccess) together with worked examples in
//   scratch:/ts/ (component.ts, catalog.ts, scene-additions.ts, examples.ts)
// examples.ts contains:
//   - a full 608-2RSH bearing: 2 parts, an internal revolute, generator-backed, with sourced dimensions and mass
//   - a 2-part potentiometer: a revolute with limits, plus a binding from angle to wiper position
// Any number that needs a datasheet is a `declare const`, so no value is invented.
// CLAUDE.md caps files at about 200 lines, so the real code splits this into identity.ts, geometry.ts, anchors.ts, schematic.ts, bindings.ts and license.ts.
// zod mapping:
//   - string unions -> z.enum
//   - kind/direction unions -> z.discriminatedUnion
//   - Brand<> -> z.string().regex(...).brand()
//   - every object -> .strict()
//   - every number -> z.number().finite()
// A local run of zod 4.6.5 confirmed four things: branded-key records work, Infinity is rejected, unknown keys are rejected, and z.toJSONSchema() works.
// Units: lengths in mm (geometry and anchors), simulation values in SI, angles in rad (to be confirmed in the Phase 8 Mate schema).

export type Brand<T, B extends string> = T & { readonly __brand: B };

/** '<namespace>/<slug>', e.g. 'official/led-5mm-red'. Namespace: [a-z][a-z0-9-]{1,31}; slug: [a-z0-9][a-z0-9._-]{0,63}. */
export type ComponentId = Brand<string, 'ComponentId'>;
/** Strict SemVer 2.0, no build metadata.
 *  MAJOR = a local key was removed or renamed (this breaks mates, wires and bindings).
 *  MINOR = additions.
 *  PATCH = mesh or metadata fixes. */
export type SemVer = Brand<string, 'SemVer'>;
export type SemVerRange = Brand<string, 'SemVerRange'>;      // '>=0.14.0 <1.0.0' | '^1.2.0'
export type Sha256Hex = Brand<string, 'Sha256Hex'>;          // 64 lowercase hex chars
/** Key unique inside ONE manifest: [a-zA-Z][a-zA-Z0-9_]{0,31}. '__proto__', 'constructor' and 'prototype' are rejected.
 *  After parsing, records are stored as Map or null-prototype objects. */
export type LocalKey = Brand<string, 'LocalKey'>;
export type SpdxExpression = Brand<string, 'SpdxExpression'>; // e.g. 'CC-BY-SA-4.0 WITH KiCad-libraries-exception'
export type HttpsUrl = Brand<string, 'HttpsUrl'>;            // https only, at most 2048 chars, opened only via the src/lib/tauri opener wrapper after the user confirms
export type PackPath = Brand<string, 'PackPath'>;            // relative POSIX path: no '..', no leading '/', no backslash, at most 200 bytes
export type UnitSymbol = Brand<string, 'UnitSymbol'>;        // must exist in the src/core/units.ts registry: 'V','A','ohm','W','N','N*m','rad/s','Pa','m3/s','lm','kg','m','1'
export type SimModelId = Brand<string, 'SimModelId'>;        // model implemented IN THE APP (src/core/sim/models), e.g. 'electrical.led'
export type GeneratorId = Brand<string, 'GeneratorId'>;      // generator implemented IN THE APP (src/core/generators), e.g. 'bearing.deepGroove'
export type BuiltinSymbolId = Brand<string, 'BuiltinSymbolId'>; // schematic symbol drawn by the app ('led','resistor','box'); packs never contain SVG
export type SandboxExpr = Brand<string, 'SandboxExpr'>;      // Phase 10 sandbox grammar, at most 2 KiB

export type Vec3 = readonly [number, number, number];
export type Quat = readonly [number, number, number, number]; // unit quaternion, three.js order [x,y,z,w]

export type Domain = 'electrical' | 'mechTranslational' | 'mechRotational' | 'fluid' | 'light' | 'data';
export type MateType = 'fixed' | 'revolute' | 'prismatic' | 'spherical';
export type ColliderKind = 'hull' | 'decomposed' | 'box' | 'trimesh' | 'none';

/** Where a number came from. Every datasheet number in an official pack carries one. */
export interface ValueSource {
  kind: 'datasheet' | 'standard' | 'measured' | 'computed' | 'estimated' | 'user';
  ref?: HttpsUrl;
  note?: string;                         // at most 280 chars, e.g. 'Table 2, typ. @ 20 mA'
  confidence: 'high' | 'medium' | 'low';
}

// ---------------------------------------------------------------- top level
export interface ComponentManifest {
  format: 'studiovd-component';
  schemaVersion: 1;
  identity: ComponentIdentity;
  parts: Record<LocalKey, ComponentPart>;        // 1..64. Multi-part: servo body+horn, bearing outer+inner ring
  rootPart: LocalKey;                            // its frame is the component frame used for placement and snapping
  materials: Record<LocalKey, MaterialRef>;
  anchors: Record<LocalKey, ComponentAnchor>;    // at most 256
  mates: Record<LocalKey, ComponentMate>;        // INTERNAL mates only; created on insert
  suggestedMates: SuggestedMate[];               // hints for mates to OTHER parts; never applied automatically
  schematic?: ComponentSchematic;                // absent for geometry-only parts (brackets, fasteners)
  bindings: Record<LocalKey, ComponentBinding>;
  placement: PlacementHints;
  thumbnails: Thumbnail[];                       // 1..4, PNG only
  license: ComponentLicense;
  authoring: AuthoringInfo;
}

export interface ComponentIdentity {
  id: ComponentId;
  version: SemVer;
  name: string;                          // at most 80 chars, plain text
  summary?: string;                      // at most 280 chars, plain text
  description?: string;                  // at most 4000 chars, plain text, never rendered as HTML
  category: readonly string[];           // 1..4 slugs, e.g. ['electrical','optoelectronics','led']
  tags: readonly string[];               // at most 32 tags, each at most 32 chars
  family?: string;                       // groups variants that share geometry (led-5mm red/green/blue)
  designatorPrefix?: string;             // [A-Z]{1,4}: 'LED','R','RV','M','SW'
  vendor?: string;
  mpn?: string;
  datasheetUrl?: HttpsUrl;
  requires: {
    app: SemVerRange;
    simModels?: Record<SimModelId, number>;    // model id -> required MAJOR version
    generators?: Record<GeneratorId, number>;  // generator id -> required MAJOR version
  };
  deprecated?: { reason: string; replacedBy?: ComponentId };
}

// ---------------------------------------------------------------- geometry and parts
export type GeometryRef =
  | { kind: 'asset';                     // normalized GLB, same rules as Phase 4.5 (mm, Y-up, recentred to bbox centre, normals)
      sha256: Sha256Hex; path: PackPath;  // 'geometry/<sha256>.glb'
      bytes: number; triangles: number;   // triangles are recounted on install; a mismatch rejects the pack
      bboxMm: { min: Vec3; max: Vec3 } }  // part-local
  | { kind: 'generated';                 // geometry made by in-app code; the pack carries parameters only
      generator: GeneratorId; generatorMajor: number;
      params: Record<string, number | string | boolean>; // validated by the generator's own zod schema
      output: LocalKey };                // which body of the generator output, e.g. 'outerRing'

export interface ComponentPart {
  name: string;                          // 'Body', 'Horn', 'Outer ring'
  geometry: GeometryRef;
  transform: { positionMm: Vec3; quaternion: Quat }; // pose in the component frame. Rigid only; scale is never allowed
  material: LocalKey;                    // default material for the whole part
  materialSlots?: Record<string, LocalKey>; // glTF material name -> material key (needs Phase 6 slots; see open questions)
  mass?: { kg: number; comMm?: Vec3; source: ValueSource }; // datasheet mass beats density x volume; maps to Part.massOverrideKg
  collider: ColliderKind;                // rings and tubes must be 'decomposed': a convex hull fills the bore
  role?: 'body' | 'moving' | 'emitter' | 'actuator' | 'fastener';
}

export type MaterialRef =
  | { kind: 'builtin'; key: string }     // stable Phase 6 built-in key, e.g. 'std.steel'
  | { kind: 'inline'; name: string;
      appearance: { colorLinear: Vec3; metalness: number; roughness: number; opacity?: number; transmission?: number;
        ior?: number;                    // 1.0..2.333 (three.js MeshPhysicalMaterial range)
        emissiveLinear?: Vec3; emissiveIntensity?: number;
        textures?: Partial<Record<'map' | 'normalMap' | 'roughnessMap' | 'metalnessMap', { sha256: Sha256Hex; path: PackPath }>> };
      physical: { densityKgM3: number; source?: ValueSource } };

// ---------------------------------------------------------------- anchors and mates
export interface AnchorFrame { originMm: Vec3; z: Vec3; x: Vec3 } // part-local, relative to the recentred GLB origin; z and x unit length and orthogonal

/** Interface tag used to match anchors for snap suggestions (an 8 mm shaft fits an 8 mm bore). */
export interface AnchorInterface {
  type: 'shaft' | 'bore' | 'threadExternal' | 'threadInternal' | 'mountFace' | 'pin' | 'socket'
      | 'panelHole' | 'panelBody' | 'flange' | 'spline' | 'custom';
  gender: 'male' | 'female' | 'neutral';
  diameterMm?: number;
  standard?: string;                     // 'M3', '608', 'NEMA17'
  custom?: string;
}

export interface ComponentAnchor {
  part: LocalKey;
  name: string;
  kind: 'point' | 'planar' | 'axial';    // same as scene Anchor.kind
  frame: AnchorFrame;
  interface?: AnchorInterface;
  role?: 'placement' | 'mount' | 'mate' | 'port' | 'reference'; // placement = frame aligned to the surface when dropped
  port?: LocalKey;                       // schematic port physically located here (e.g. the LED anode lead)
}

export interface ComponentMate {
  name: string;
  type: MateType;
  anchorA: LocalKey; anchorB: LocalKey;  // both must be this component's anchors
  flip: boolean;
  angleOffsetRad: number;
  limits?: { min: number; max: number; source?: ValueSource }; // rad (revolute), mm (prismatic), cone half-angle rad (spherical)
  contactsEnabled: boolean;
}

export interface SuggestedMate {
  anchor: LocalKey;
  matches: { type: AnchorInterface['type']; diameterMm?: number; toleranceMm?: number; standard?: string };
  mateType: MateType;
  flip: boolean;
  label: string;                         // 'Press into a 5 mm panel hole'
}

export interface PlacementHints {
  placementAnchor?: LocalKey;            // its z is aligned to -surfaceNormal under the cursor
  groundIfFirst: boolean;                // Phase 4.7 rule: the first part in a scene is grounded
  totalTriangles: number;                // budget check (CLAUDE.md section 6: about 2-3 M triangles across 200 parts)
}

// ---------------------------------------------------------------- schematic (Phase 10/11)
export type PortSide = 'left' | 'right' | 'top' | 'bottom';
export type PortDef =
  | { domain: 'electrical' | 'mechTranslational' | 'mechRotational' | 'fluid'; direction: 'terminal'; label: string; side: PortSide; order: number }
  | { domain: 'light' | 'data'; direction: 'in' | 'out'; unit: UnitSymbol; label: string; side: PortSide; order: number; defaultValue?: number };

export interface ParamDef {
  label: string;
  unit: UnitSymbol;                      // stored in SI
  displayUnit?: UnitSymbol;              // e.g. 'mA', 'rpm'; converted only through units.ts
  default: number; min?: number; max?: number; scale?: 'linear' | 'log';
  editable: boolean;
  usedBy: readonly ('steady' | 'transient')[]; // transient-only params (L, C, J) are kept for a later phase and ignored by the v1 solver
  source?: ValueSource;
}

export interface Rating {
  label: string;
  quantity: { kind: 'portFlow'; port: LocalKey } | { kind: 'portEffort'; port: LocalKey; reference?: LocalKey }
          | { kind: 'power' } | { kind: 'expr'; expr: SandboxExpr };
  unit: UnitSymbol; min?: number; max?: number;
  severity: 'warning' | 'error';
  source?: ValueSource;
}

export type BlockBehaviour =
  | { kind: 'model';                     // code ships IN THE APP; the pack only names it and maps ports and params
      model: SimModelId; modelMajor: number;
      portMap: Record<string, LocalKey>; paramMap: Record<string, LocalKey> }
  | { kind: 'expression';                // Phase 10.5 black-box behaviour, sandboxed
      locals?: Record<LocalKey, SandboxExpr>;  // must not reference each other cyclically
      equations: readonly { target: { kind: 'flow'; port: LocalKey } | { kind: 'signal'; port: LocalKey }; expr: SandboxExpr }[] };
// Reserved for schemaVersion 2: { kind: 'composite' } sub-circuits of model/expression blocks.

export interface BlockDefinition {
  ports: Record<LocalKey, PortDef>;      // at most 64
  params: Record<LocalKey, ParamDef>;    // at most 128
  behaviour: BlockBehaviour;
  ratings: readonly Rating[];
}

export interface ComponentSchematic {
  block: BlockDefinition;
  symbol: { kind: 'builtin'; id: BuiltinSymbolId } | { kind: 'box'; label?: string };
  linkedParts?: readonly LocalKey[];     // cross-selection set (Phase 10.6); defaults to all parts
}

// ---------------------------------------------------------------- default bindings (Phase 12). PLAN D3: measurements in, visuals out; sim never moves parts.
export interface ExternalSlot { kind: 'external'; prompt: string } // e.g. 'Pick the part that presses the lever'; binding stays inactive until resolved
export interface LocalPartRef { kind: 'part'; part: LocalKey }
export interface LocalAnchorRef { kind: 'anchor'; anchor: LocalKey }

export type MeasurementSource =          // 3D -> sim
  | { kind: 'mateCoordinate'; mate: LocalKey }            // rad or mm
  | { kind: 'gravityLoad'; mate: LocalKey }               // N*m (revolute) or N (prismatic), PLAN.md section 2
  | { kind: 'mass'; parts: readonly LocalKey[] }          // kg
  | { kind: 'contact'; a: LocalPartRef; b: LocalPartRef | ExternalSlot }        // 0 or 1
  | { kind: 'anchorDistance'; a: LocalAnchorRef; b: LocalAnchorRef | ExternalSlot }; // converted to m
export type MeasurementTarget =
  | { kind: 'param'; param: LocalKey } | { kind: 'signalInput'; port: LocalKey }
  | { kind: 'mechanicalSource'; port: LocalKey };        // gravity load enters as a source on a mechanical port
export type ResultSource =               // sim -> 3D
  | { kind: 'port'; port: LocalKey; quantity: 'effort' | 'flow' | 'signal' | 'power' }
  | { kind: 'rating'; index: number };                    // 0 ok, 1 warning, 2 error
export type VisualTarget =
  | { kind: 'emissive'; part: LocalKey; slot?: string; colorLinear: Vec3 }
  | { kind: 'tint'; part: LocalKey; colorLinear: Vec3 }
  | { kind: 'forceArrow'; anchor: LocalKey }
  | { kind: 'label'; anchor: LocalKey; unit: UnitSymbol; digits: number };
export type BindingMap =
  | { kind: 'identity' }
  | { kind: 'linear'; from: readonly [number, number]; to: readonly [number, number]; clamp: boolean }
  | { kind: 'threshold'; at: number; below: number; above: number }
  | { kind: 'expr'; expr: SandboxExpr };                  // one free variable: x
export type ComponentBinding =
  | { direction: 'measurement'; label: string; source: MeasurementSource; target: MeasurementTarget; map: BindingMap; enabled: boolean }
  | { direction: 'visual'; label: string; source: ResultSource; target: VisualTarget; map: BindingMap; enabled: boolean };
// Examples:
//   potentiometer: mateCoordinate(rot) -> param(pos), linear [0, ROT_RAD] -> [0, 1]
//   LED:           port(light, signal) -> emissive(lens)
//   motor/servo:   gravityLoad(shaftMate) -> mechanicalSource(shaft)
//   limit switch:  contact(lever, external) -> signalInput(closed)

// ---------------------------------------------------------------- thumbnails, license, authoring
export interface Thumbnail { path: PackPath; sha256: Sha256Hex; widthPx: number; heightPx: number } // PNG, at most 512x512

export interface LicenseGrant {
  spdx: SpdxExpression;                  // 'LicenseRef-...' allowed for user/private content
  creators: readonly { name: string; url?: HttpsUrl }[];
  copyright?: string;                    // copyright notice as the licensor supplied it
  sourceUrl?: HttpsUrl;                  // URI of the licensed material (CC BY-SA 4.0, 3(a)(1)(A)(v))
  sourceRevision?: string;               // upstream git commit
  modifications?: string;                // 'STEP tessellated to GLB, recentred, Y-up' (CC BY-SA 4.0, 3(a)(1)(B))
  licenseUrl?: HttpsUrl;
  licenseText?: { path: PackPath; sha256: Sha256Hex }; // required when the license demands a copy of its text (MIT, BSD, Apache-2.0)
  attributionRequired: boolean;
  redistributable: boolean;              // false = vendor model with no-redistribution terms (user library only)
}
export interface ComponentLicense {
  geometry: LicenseGrant;                // GLBs and textures
  data: LicenseGrant;                    // anchors, params, bindings, text (curation)
  thumbnail?: LicenseGrant;              // defaults to geometry
  inherited?: readonly { component: ComponentId; version: SemVer; geometry: SpdxExpression }[]; // kept by Save as component
}

export type AuthoringInfo =
  | { kind: 'pipeline'; tool: string; toolVersion: string; builtAt: string }
  | { kind: 'generator'; generator: GeneratorId; generatorVersion: SemVer; params: Record<string, number | string | boolean> }
  | { kind: 'user'; appVersion: string; createdAt: string; author?: string };

// Mapping multi-part components to parts and mates:
//   - Each entry in parts becomes one scene Part.
//   - Each entry in mates becomes one scene Mate between the instance's own anchors.
//   - Servo = body + horn. Revolute mate body.outputAxis <-> horn.hubAxis, with limits; gravityLoad(hornMate) -> mechanicalSource(shaft).
//     Under D3 a commanded angle can only be shown as a visual; it never moves the horn.
//   - Bearing = outer ring + inner ring. Revolute, contactsEnabled false (balls are not modelled), both rings use collider 'decomposed'.
//   - Pot = body + shaft. Revolute with limits, plus a binding from the mate angle to the wiper position.
//   - LED = 1 part with material slots (lens, leads), or 3 fixed-mated parts if Phase 6 rejects slots.
//     Fixed mates are merged into one rigid body anyway (PLAN 1.1 #5).

catalog_index_ts:
// Proposed files: src/core/schema/library/catalog.ts and pack.ts (typechecked, same scratch folder).
import type { Brand, ComponentId, Domain, GeneratorId, HttpsUrl, PackPath, SemVer, SemVerRange, Sha256Hex, SimModelId, SpdxExpression } from './component';

export type CatalogId = Brand<string, 'CatalogId'>;   // 'official' is reserved: valid only for an index signed by a compiled-in key
export type PackId = Brand<string, 'PackId'>;         // = SHA-256 of the pack zip (content-addressed)
export type RelUrl = Brand<string, 'RelUrl'>;         // relative to a mirror base, e.g. 'catalog-42/official.led-5mm-red-1.0.0.stvdpack'
export type IsoUtc = Brand<string, 'IsoUtc'>;         // RFC 3339 UTC

// Files at a mirror base URL:
//   index.json          this interface, UTF-8, at most 16 MiB (streamed with a byte cap)
//   index.json.minisig  minisign signature, prehashed Ed25519 (BLAKE2b-512)
//                       trusted comment = 'studiovd-catalog <catalogId> seq=<sequence> expires=<expiresAt>'
// minisign also signs the trusted comment: minisign-verify 0.3.0 verifies a global signature over signature || trusted_comment.
// Verification is done in Rust with minisign-verify 0.3.0: MIT, no external dependencies, already a dependency of tauri-plugin-updater 2.13.2.
// It is called with allow_legacy = false, so only prehashed signatures are accepted.
export interface CatalogIndex {
  format: 'studiovd-catalog';
  schemaVersion: 1;
  catalogId: CatalogId;
  sequence: number;                    // strictly increasing; the client stores the highest verified value (rollback guard)
  generatedAt: IsoUtc;
  expiresAt: IsoUtc;                   // the client refuses to INSTALL from an expired index (freeze guard); installed content keeps working
  minAppVersion: SemVer;
  signingKeyId: string;                // minisign key id, 16 hex chars
  mirrors: readonly HttpsUrl[];        // tried in order; integrity never depends on which mirror served the file
  categories: readonly CategoryNode[];
  components: readonly CatalogComponentEntry[];
  packs: Readonly<Record<PackId, PackEntry>>;
  bundles: readonly BundleEntry[];
  previewPacks: Readonly<Record<string, PackId>>;  // 'electrical/passive' -> thumbnails-only pack (few requests while browsing)
  generatorPresets: readonly GeneratorPresetEntry[];
  revoked: readonly RevokedEntry[];
  notices: readonly { id: string; severity: 'info' | 'warning'; text: string }[]; // plain text, never HTML
}
export interface CategoryNode { path: readonly string[]; label: string; order: number }
export interface CatalogComponentEntry {
  id: ComponentId; version: SemVer; name: string; summary: string;
  category: readonly string[]; tags: readonly string[]; family?: string; vendor?: string; mpn?: string;
  domains: readonly Domain[];          // [] = geometry-only
  partCount: number; triangles: number; hasSchematic: boolean;
  license: { geometry: SpdxExpression; data: SpdxExpression };
  requires: { app: SemVerRange; simModels?: Readonly<Record<SimModelId, number>>; generators?: Readonly<Record<GeneratorId, number>> };
  manifestSha256: Sha256Hex;           // hash of the exact component.json bytes: anchors the hash chain
  pack: PackId;                        // smallest pack containing it (normally a 1-component pack)
  thumbnail: { pack: PackId; path: PackPath; sha256: Sha256Hex };
  publishedAt: IsoUtc;
  deprecated?: { reason: string; replacedBy?: ComponentId };
}
export interface PackEntry {
  url: RelUrl;
  sha256: Sha256Hex;                   // == PackId, checked BEFORE the zip is opened
  bytes: number;                       // the download is aborted past this size (endless-data guard)
  uncompressedBytes: number;           // extraction is aborted past this size
  entries: number;
}
export interface BundleEntry { id: string; label: string; pack: PackId; components: readonly { id: ComponentId; version: SemVer }[] }
/** Virtual components: no geometry download; geometry is made by in-app generator code. */
export interface GeneratorPresetEntry {
  id: ComponentId;                     // 'gen/bearing-608-2rsh'
  version: SemVer; name: string; category: readonly string[]; tags: readonly string[];
  generator: GeneratorId; generatorMajor: number;
  params: Readonly<Record<string, number | string | boolean>>;
  manifestSha256: Sha256Hex;
  pack: PackId;                        // tiny pack: component.json + thumbnail only
}
export interface RevokedEntry { id: ComponentId; version: SemVer; reason: string; severity: 'yanked' | 'security' }

// pack.json at the root of every .stvdpack: single component, category bundle, preview pack, or user export.
export interface PackManifest {
  format: 'studiovd-pack';
  schemaVersion: 1;
  createdBy: string;                   // 'studiovd-pack-builder 1.0.0' | 'StudioVD 0.14.0'
  createdAt: IsoUtc;
  components: readonly { id: ComponentId; version: SemVer; manifestPath: PackPath; manifestSha256: Sha256Hex }[];
  files: readonly { path: PackPath; sha256: Sha256Hex; bytes: number }[]; // any zip entry not listed here => reject the pack
  embeddedIndex?: { indexPath: PackPath; signaturePath: PackPath };     // lets offline bundles verify as official
}

// Client state, stored at library/catalogs/<catalogId>/state.json (never inside packs).
export interface CatalogClientState { catalogId: CatalogId; highestSequence: number; lastFetchedAt?: IsoUtc; lastVerifiedKeyId?: string }

// Chain of trust:
//   1. compiled-in public keys (at least 2: active + offline backup; test keys only in cfg(test)/debug builds)
//   2. index.json.minisig verifies index.json
//   3. PackEntry.sha256 verifies the downloaded zip
//   4. pack.json lists every file with its SHA-256
//   5. CatalogComponentEntry.manifestSha256 verifies component.json
//   6. component.json lists the SHA-256 of every GLB, PNG and license text, and content-addressed file names must match.
// Because steps 5 and 6 do not depend on the pack hash, a bundle or a component pulled from someone's .stvd can still be verified as official offline,
// either against a cached signed index or against the bundle's embedded index.
// Threats covered (TUF spec 1.0.37 terms): arbitrary installation, endless data, rollback, indefinite freeze, mix-and-match (one signed index pins every hash), malicious mirrors.
// Threats NOT covered in v1: threshold keys and key-compromise recovery beyond shipping a new app build that rotates keys.
// Hosting: GitHub Releases on a separate repo (proposed: bmisho/StudioVD-library).
//   - Stable index URL: https://github.com/bmisho/StudioVD-library/releases/latest/download/index.json (GitHub documents the /releases/latest/download/<asset> pattern).
//   - Limits: at most 1000 assets per release, each file under 2 GiB, no limit on total size or bandwidth (github/docs about-releases.md + data/variables).
//   - Each catalog publish is one immutable release 'catalog-<sequence>' that carries only new or changed packs plus index.json/.minisig.
//   - The index references packs in older releases by RelUrl.
//   - Immutable releases (GA 2025-10-28) stop assets being swapped after publishing. This is defence in depth; integrity already comes from the signature.

mapping_to_scene_json:
Schema additions, proposed for the Phase 5 scene.json v1 so that no migration is needed later (typechecked in scratch ts/scene-additions.ts):
- componentDefs: Record<ComponentDefKey, ComponentDefSnapshot> = { key, id, version, manifestSha256, manifest (full validated copy), origin, firstInsertedAt, blockDefId? }
- components: Record<ComponentInstanceId, ComponentInstance> = { id, def, designator, groupId, parts/anchors/mates/materials/bindings (each Record<LocalKey, EntityId>), nodeId?, unlinked? }
- licenseTexts: Record<Sha256, { path: 'licenses/<sha>.txt', spdx }>
Field additions:
- Part.componentRef? = { instance, key }
- Part.materialSlots? and Part.comOverrideMm? (both open questions)
- Anchor.source gains { kind: 'component', instance, key }: the frame is authoritative and no face id is stored, so anchors never depend on the face-segmentation version
- Material.provenance? = { builtinKey? | def+key }
New bundle folder: licenses/.
